from docx import Document
from docx.shared import Pt, RGBColor, Inches
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.enum.table import WD_TABLE_ALIGNMENT
from docx.oxml.ns import qn
from docx.oxml import OxmlElement
import re

SEV_COL = {"Critical":"C00000","High":"E46C0A","Medium":"BF9000","Low":"548235"}

def shade(cell, hexcol):
    tcPr = cell._tc.get_or_add_tcPr()
    shd = OxmlElement("w:shd")
    shd.set(qn("w:val"), "clear"); shd.set(qn("w:color"), "auto"); shd.set(qn("w:fill"), hexcol)
    tcPr.append(shd)

def rich(p, text, size=None, color=None):
    # **bold** and *italic* markup
    parts = re.split(r"(\*\*[^*]+\*\*|\*[^*]+\*)", text)
    for part in parts:
        if not part: continue
        if part.startswith("**"):
            r = p.add_run(part[2:-2]); r.bold = True
        elif part.startswith("*"):
            r = p.add_run(part[1:-1]); r.italic = True
        else:
            r = p.add_run(part)
        if size: r.font.size = Pt(size)
        if color: r.font.color.rgb = RGBColor.from_string(color)
    return p

def new_doc():
    d = Document()
    st = d.styles["Normal"]; st.font.name = "Calibri"; st.font.size = Pt(10.5)
    st.element.rPr.rFonts.set(qn("w:eastAsia"), "Calibri")
    for s in d.sections:
        s.left_margin = s.right_margin = Inches(0.9); s.top_margin = s.bottom_margin = Inches(0.8)
    for lvl, sz in ((1,14),(2,12),(3,11)):
        h = d.styles["Heading %d" % lvl]; h.font.name = "Calibri"; h.font.size = Pt(sz)
        h.font.color.rgb = RGBColor(0x1F,0x3A,0x5F)
    return d

def para(d, text, style=None, size=None, align=None, space_after=6):
    p = d.add_paragraph(style=style) if style else d.add_paragraph()
    rich(p, text, size=size)
    p.paragraph_format.space_after = Pt(space_after)
    if align == "c": p.alignment = WD_ALIGN_PARAGRAPH.CENTER
    return p

def bullet(d, text, level=0):
    p = d.add_paragraph(style="List Bullet" if level==0 else "List Bullet 2")
    rich(p, text); p.paragraph_format.space_after = Pt(3)
    return p

def num(d, text):
    p = d.add_paragraph(style="List Number"); rich(p, text); p.paragraph_format.space_after = Pt(3)
    return p

def table(d, header, rows, widths=None, sevcol=None, size=9, hdr_fill="1F3A5F"):
    t = d.add_table(rows=1, cols=len(header))
    t.style = "Table Grid"; t.alignment = WD_TABLE_ALIGNMENT.CENTER
    for i, h in enumerate(header):
        c = t.rows[0].cells[i]; c.text = ""
        rich(c.paragraphs[0], "**%s**" % h, size=size, color="FFFFFF"); shade(c, hdr_fill)
    for row in rows:
        cells = t.add_row().cells
        for i, v in enumerate(row):
            cells[i].text = ""
            lines = str(v).split("\n")
            for j, ln in enumerate(lines):
                pp = cells[i].paragraphs[0] if j == 0 else cells[i].add_paragraph()
                rich(pp, ln, size=size)
            if sevcol is not None and i == sevcol:
                key = str(v).split()[0].strip("*")
                if key in SEV_COL:
                    shade(cells[i], SEV_COL[key])
                    for r in cells[i].paragraphs[0].runs:
                        r.font.color.rgb = RGBColor(0xFF,0xFF,0xFF); r.bold = True
    if widths:
        for row in t.rows:
            for i, w in enumerate(widths):
                row.cells[i].width = Inches(w)
    # repeat header
    trPr = t.rows[0]._tr.get_or_add_trPr(); th = OxmlElement("w:tblHeader"); th.set(qn("w:val"), "true"); trPr.append(th)
    d.add_paragraph().paragraph_format.space_after = Pt(2)
    return t
EOF
